partsCss:
/* Hero Comic v2, rounded corners: manga pages from mha-ultimate-2-0. Ink panels, white keylines, hard offset
   shadows, halftone, speed lines, yellow and red.
   Layout-neutral: keylines and frames are drawn with box-shadow, slants with clip-path,
   so no part changes size and text stays on its line. */
[data-skin-part="app-shell"] { background-color: #0a0c10; }
[data-skin-part="app-shell"] ::selection { background: #ffd21f; color: #111111; }

/* Chat page: plain ink with a faint halftone screen. */
[data-skin-part="chat-screen"] {
  background-color: #0d0f14;
  background-image: radial-gradient(rgb(255 255 255 / .05) 1.1px, transparent 1.7px);
  background-size: 8px 8px;
}
/* Settings page: halftone that fades out from the top. */
[data-skin-part="settings-page"] {
  background-image:
    linear-gradient(180deg, transparent 0, #0d0f14 260px),
    radial-gradient(rgb(255 210 31 / .14) 1.1px, transparent 1.7px);
  background-size: 100% 100%, 8px 8px;
}

/* Red rail with a heavy ink edge. */
[data-skin-part="sidebar-rail"] {
  background-color: #b91c24 !important;
  background-image: linear-gradient(180deg, #c9202a 0%, #a3141c 55%, #6e0b11 100%) !important;
  box-shadow: inset -3px 0 0 #000000;
  /* Keep yellow off the rail: its menu button, selection outline and markers use white. */
  --color-primary: #f4f5f7;
  --risu-theme-primary: #f4f5f7;
  --color-borderc: #f4f5f7;
  --risu-theme-borderc: #f4f5f7;
}
[data-skin-part="rail-icon"] { box-shadow: 0 0 0 1px #000000; }
[data-skin-part="rail-icon"]:hover { box-shadow: 0 0 0 1px #000000, 0 0 0 2px #f4f5f7; }
[data-skin-part="rail-icon"][data-skin-state="active"] {
  box-shadow: 0 0 0 1px #000000, 0 0 0 3px #f4f5f7 !important;
}

/* Side panel: plain, with the rail's ink edge. */
[data-skin-part="sidebar-panel"] { box-shadow: inset -3px 0 0 #000000; }

/* Settings navigation: the current page as a yellow panel with a red offset. */
[data-skin-part="settings-nav"] { box-shadow: inset -3px 0 0 #000000; }
[data-skin-part="settings-nav"] [aria-current="page"] {
  background: #ffd21f !important;
  color: #111111 !important;
  box-shadow: 0 0 0 1px #000000, 2px 2px 0 1px #e3262f;
}

/* Page title: heavy display face, ink outline, red offset, slanted underline slab. */
[data-skin-part="settings-page"] h1 {
  font-family: var(--risu-font-display);
  color: #ffd21f;
  letter-spacing: .02em;
  text-shadow: -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000, 1px 1px 0 #000, 4px 4px 0 #e3262f;
}
[data-skin-part="settings-page"] h1::after {
  content: ""; display: block; width: 88px; height: 7px; margin-top: .55rem;
  background: #f4f5f7;
  box-shadow: 4px 4px 0 #e3262f;
  border-radius: 999px;
}

/* Tabs: the active tab becomes a yellow panel with an ink edge and a hard shadow.
   No slant: a clip-path cut into the label at the corners. */
[data-skin-part="tab"][data-skin-state="active"] {
  background: #ffd21f !important;
  color: #111111 !important;
  box-shadow: 0 0 0 1px #000000, 2px 2px 0 1px #000000;
}
[data-skin-part="tab"][data-skin-state="active"]::after { display: none !important; }

/* Buttons: ink keyline and hard shadow; pressing pushes the button into its shadow. */
[data-skin-part="button"]:is([data-skin-variant="default"], [data-skin-variant="outline"], [data-skin-variant="secondary"], [data-skin-variant="binding"], [data-skin-variant="destructive"]) {
  box-shadow: 0 0 0 1px #000000, 3px 3px 0 #000000;
  transition: transform .08s ease, box-shadow .08s ease;
}
[data-skin-part="button"][data-skin-variant="primary"] {
  background: #ffd21f !important;
  color: #111111 !important;
  border-color: #000000 !important;
  box-shadow: 0 0 0 1px #000000, 4px 4px 0 #e3262f, 4px 4px 0 1px #000000;
  transition: transform .08s ease, box-shadow .08s ease;
}
[data-skin-part="button"][data-skin-variant="primary"]:hover:not(:disabled) {
  transform: translate(-1px, -1px);
  box-shadow: 0 0 0 1px #000000, 5px 5px 0 #e3262f, 5px 5px 0 1px #000000;
}
[data-skin-part="button"]:not([data-skin-variant="ghost"]):not([data-skin-variant="link"]):active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 0 0 0 1px #000000, 1px 1px 0 #000000;
}
[data-skin-part="button"]:is([data-skin-variant="default"], [data-skin-variant="outline"], [data-skin-variant="secondary"]):hover:not(:disabled) {
  border-color: #ffd21f !important;
}

/* Fields: yellow focus with a red offset. */
[data-skin-part="input"]:focus, [data-skin-part="input"]:focus-within {
  border-color: #ffd21f !important;
  box-shadow: 0 0 0 1px #ffd21f, 3px 3px 0 1px #e3262f !important;
}
[data-skin-part="checkbox"][data-skin-state="checked"] {
  background: #ffd21f !important; border-color: #000000 !important; color: #111111 !important;
  box-shadow: 2px 2px 0 #000000;
}
[data-skin-part="switch"] { box-shadow: 0 0 0 1px #000000, 2px 2px 0 #000000; }
[data-skin-part="chip"] { box-shadow: 2px 2px 0 #000000; }

/* Windows: comic panel with white keyline, ink frame and a yellow offset page behind it. */
[data-skin-part="modal"] {
  border-color: #f4f5f7 !important;
  background-image:
    linear-gradient(200deg, transparent 0, var(--color-darkbg) 220px),
    radial-gradient(rgb(255 210 31 / .3) 1.1px, transparent 1.7px) !important;
  background-size: 100% 100%, 8px 8px !important;
  box-shadow: 0 0 0 3px #000000, 10px 10px 0 3px #ffd21f, 10px 10px 0 6px #000000 !important;
}
[data-skin-part="menu"] {
  border-color: #f4f5f7 !important;
  box-shadow: 0 0 0 2px #000000, 5px 5px 0 2px #000000 !important;
}

/* Composer: speech balloon frame; yellow with a red shadow while typing. */
[data-skin-part="composer-field"] {
  border-color: #f4f5f7 !important;
  box-shadow: 0 0 0 2px #000000, 5px 5px 0 2px #000000;
}
[data-skin-part="composer-field"]:focus-within {
  border-color: #ffd21f !important;
  box-shadow: 0 0 0 2px #000000, 5px 5px 0 2px #e3262f;
}

/* Message rows stay clear so speed lines and dots show between the panels. */
[data-skin-part="message"] { background-color: transparent !important; }
/* Message cards as comic panels: white keyline, ink frame, offset shadow, halftone corner.
   Bot panels throw a black shadow, the user's panels a yellow keyline and red shadow. */
[data-skin-part="message"][data-skin-role="bot"] [data-skin-part="message-card"] {
  background-image:
    linear-gradient(205deg, transparent 0, #0d0f14 190px),
    radial-gradient(rgb(255 255 255 / .16) 1.1px, transparent 1.7px);
  background-size: 100% 100%, 8px 8px;
  box-shadow: inset 0 0 0 2px #f4f5f7, 0 0 0 3px #000000, 7px 7px 0 3px #000000;
}
[data-skin-part="message"][data-skin-role="user"] [data-skin-part="message-card"] {
  background-image:
    linear-gradient(155deg, transparent 0, #0d0f14 170px),
    radial-gradient(rgb(255 210 31 / .22) 1.1px, transparent 1.7px);
  background-size: 100% 100%, 8px 8px;
  box-shadow: inset 0 0 0 2px #ffd21f, 0 0 0 3px #000000, 7px 7px 0 3px #e3262f;
}
/* Phones: the cards run edge to edge, so the frame drops its side shadow and keeps a bottom slab. */
@media (max-width: 639px) {
  [data-skin-part="message"][data-skin-role="bot"] [data-skin-part="message-card"] { box-shadow: inset 0 0 0 2px #f4f5f7, 0 5px 0 #000000; }
  [data-skin-part="message"][data-skin-role="user"] [data-skin-part="message-card"] { box-shadow: inset 0 0 0 2px #ffd21f, 0 5px 0 #e3262f; }
}

/* --- rounded set --- */
/* One rule for every control: anything one line tall is a pill, like the message composer.
   Panels, cards and text areas follow the larger radius tokens. Rail thumbnails and menu
   buttons are circles, like the persona avatar and the send buttons. */
[data-skin-part="button"]:not([data-skin-variant="link"]),
[data-skin-part="input"]:not(:has(textarea)),
[data-skin-part="tabs"],
[data-skin-part="tab"],
[data-skin-part="chip"],
[data-skin-part="switch"],
[data-skin-part="checkbox"] { border-radius: 9999px !important; }
[data-skin-part="rail-icon"],
[data-skin-part="rail-icon"] :is(img, div, span),
[data-skin-part="sidebar-rail"] :is(button, img) { border-radius: 9999px !important; }
